public class InnerDataAutomationProjectVideoStandardExtractionFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardExtraction> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardExtraction>
{

    internal InnerDataAutomationProjectVideoExtractionCategoryFactory CategoryFactory { get; set; }

    internal InnerDataAutomationProjectVideoBoundingBoxFactory BoundingBoxFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardExtraction Create()
    {
        var videoStandardExtractionResult = CreateVideoStandardExtraction();
        factoryAction?.Invoke(videoStandardExtractionResult);

        return videoStandardExtractionResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardExtraction CreateVideoStandardExtraction()
    {
        var videoStandardExtractionResult = new Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardExtraction();

        return videoStandardExtractionResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardExtraction result)
    {
        base.CreateChildren(result);

        result.Category ??= CategoryFactory?.Build();
        result.BoundingBox ??= BoundingBoxFactory?.Build();
    }

} // End Of Class

